def run_circular_queue_ops(k, ops):
    data = [0] * k
    head = 0
    count = 0
    output = []

    for op, arg in ops:
        if op == 'enQueue':
            if count == k:
                output.append(False)
            else:
                data[(head + count) % k] = arg
                count += 1
                output.append(True)
        elif op == 'deQueue':
            if count == 0:
                output.append(False)
            else:
                head = (head + 1) % k
                count -= 1
                output.append(True)
        elif op == 'Front':
            output.append(data[head] if count > 0 else -1)
        elif op == 'Rear':
            output.append(data[(head + count - 1) % k] if count > 0 else -1)
        elif op == 'isEmpty':
            output.append(count == 0)
        elif op == 'isFull':
            output.append(count == k)

    return output

